package cue

import (
	_ "embed"
	"errors"
	"fmt"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	cueerrors "cuelang.org/go/cue/errors"
	cueyaml "cuelang.org/go/encoding/yaml"
	"gopkg.in/yaml.v3"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error describes a validation problem and where it occurred in the source file.
type Error struct {
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

// Result is the JSON representation of validation issues.
type Result struct {
	Errors []Error `json:"errors"`
}

func (e Error) Error() string {
	return fmt.Sprintf("%s (%s %d:%d)", e.Message, e.Location.File, e.Location.Line, e.Location.Column)
}

type validationErrors struct {
	errors []error
}

func (e validationErrors) Error() string { return errors.Join(e.errors...).Error() }

func (e validationErrors) Is(target error) bool { return target == ErrValidationFailed }

func (e validationErrors) Unwrap() []error { return e.errors }

// Unwrap returns the individual errors contained in a validation error.
func Unwrap(err error) ([]error, bool) {
	if err == nil {
		return nil, false
	}

	var multi interface{ Unwrap() []error }
	if !errors.As(err, &multi) {
		return nil, false
	}

	return multi.Unwrap(), true
}

type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if v.Err() != nil {
		return nil, v.Err()
	}

	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate validates a YAML file against our CUE definition of features and
// checks references between flags, variants, and segments.
func Validate(file string, contents []byte) error {
	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}

	return validator.Validate(file, contents)
}

// Validate validates a YAML file against our CUE definition of features and
// checks references between flags, variants, and segments.
func (v FeaturesValidator) Validate(file string, contents []byte) error {
	f, err := cueyaml.Extract("", contents)
	if err != nil {
		return validationError(file, err)
	}

	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil {
		return validationError(file, err)
	}

	if err := v.v.Unify(yv).Validate(cue.All(), cue.Concrete(true)); err != nil {
		return validationError(file, err)
	}

	var root yaml.Node
	if err := yaml.Unmarshal(contents, &root); err != nil {
		return validationError(file, err)
	}

	return validateReferences(file, &root)
}

func validationError(file string, err error) error {
	var individual []error
	for _, e := range cueerrors.Errors(err) {
		location := Location{File: file, Line: 1, Column: 1}
		if positions := cueerrors.Positions(e); len(positions) > 0 {
			p := positions[len(positions)-1]
			location.Line = p.Line()
			location.Column = p.Column()
		}
		individual = append(individual, Error{Message: e.Error(), Location: location})
	}

	if len(individual) == 0 {
		individual = append(individual, Error{
			Message: err.Error(),
			Location: Location{
				File:   file,
				Line:   1,
				Column: 1,
			},
		})
	}

	return validationErrors{errors: individual}
}

func validateReferences(file string, root *yaml.Node) error {
	root = documentNode(root)
	if root == nil || root.Kind != yaml.MappingNode {
		return nil // The CUE validation above reports malformed documents.
	}

	segments := map[string]struct{}{}
	if entries := mappingValue(root, "segments"); entries != nil && entries.Kind == yaml.SequenceNode {
		for _, segment := range entries.Content {
			if key := scalarValue(mappingValue(segment, "key")); key != "" {
				segments[key] = struct{}{}
			}
		}
	}

	namespace := scalarValue(mappingValue(root, "namespace"))
	if namespace == "" {
		namespace = "default"
	}

	var individual []error
	flags := mappingValue(root, "flags")
	if flags == nil || flags.Kind != yaml.SequenceNode {
		return nil
	}

	for _, flag := range flags.Content {
		flagKey := scalarValue(mappingValue(flag, "key"))
		variants := map[string]struct{}{}
		if variantNodes := mappingValue(flag, "variants"); variantNodes != nil && variantNodes.Kind == yaml.SequenceNode {
			for _, variant := range variantNodes.Content {
				if key := scalarValue(mappingValue(variant, "key")); key != "" {
					variants[key] = struct{}{}
				}
			}
		}

		if rules := mappingValue(flag, "rules"); rules != nil && rules.Kind == yaml.SequenceNode {
			for ruleIndex, rule := range rules.Content {
				for _, reference := range segmentReferences(mappingValue(rule, "segment")) {
					if _, ok := segments[reference.value]; !ok {
						individual = append(individual, sourceError(file, reference.node,
							fmt.Sprintf("flag %s/%s rule %d references unknown segment %q", namespace, flagKey, ruleIndex, reference.value)))
					}
				}

				distributions := mappingValue(rule, "distributions")
				if distributions == nil || distributions.Kind != yaml.SequenceNode {
					continue
				}
				for _, distribution := range distributions.Content {
					variantNode := mappingValue(distribution, "variant")
					variantKey := scalarValue(variantNode)
					if _, ok := variants[variantKey]; !ok {
						individual = append(individual, sourceError(file, variantNode,
							fmt.Sprintf("flag %s/%s rule %d references unknown variant %q", namespace, flagKey, ruleIndex, variantKey)))
					}
				}
			}
		}

		// Boolean flags use rollouts rather than distributions, but their segment
		// references need the same referential integrity check.
		if rollouts := mappingValue(flag, "rollouts"); rollouts != nil && rollouts.Kind == yaml.SequenceNode {
			for rolloutIndex, rollout := range rollouts.Content {
				for _, reference := range segmentReferences(mappingValue(rollout, "segment")) {
					if _, ok := segments[reference.value]; !ok {
						individual = append(individual, sourceError(file, reference.node,
							fmt.Sprintf("flag %s/%s rollout %d references unknown segment %q", namespace, flagKey, rolloutIndex, reference.value)))
					}
				}
			}
		}
	}

	if len(individual) == 0 {
		return nil
	}
	return validationErrors{errors: individual}
}

type segmentReference struct {
	value string
	node  *yaml.Node
}

func segmentReferences(node *yaml.Node) []segmentReference {
	if node == nil {
		return nil
	}

	if node.Kind == yaml.ScalarNode {
		return []segmentReference{{value: node.Value, node: node}}
	}
	if node.Kind != yaml.MappingNode {
		return nil
	}

	if keyNode := mappingValue(node, "key"); keyNode != nil {
		return []segmentReference{{value: scalarValue(keyNode), node: keyNode}}
	}

	keys := mappingValue(node, "keys")
	if keys == nil || keys.Kind != yaml.SequenceNode {
		return nil
	}
	references := make([]segmentReference, 0, len(keys.Content))
	for _, key := range keys.Content {
		references = append(references, segmentReference{value: scalarValue(key), node: key})
	}
	return references
}

func sourceError(file string, node *yaml.Node, message string) Error {
	location := Location{File: file, Line: 1, Column: 1}
	if node != nil {
		location.Line = node.Line
		location.Column = node.Column
	}
	return Error{Message: message, Location: location}
}

func documentNode(node *yaml.Node) *yaml.Node {
	if node != nil && node.Kind == yaml.DocumentNode && len(node.Content) > 0 {
		return node.Content[0]
	}
	return node
}

func mappingValue(node *yaml.Node, key string) *yaml.Node {
	if node == nil || node.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(node.Content); i += 2 {
		if node.Content[i].Value == key {
			return node.Content[i+1]
		}
	}
	return nil
}

func scalarValue(node *yaml.Node) string {
	if node == nil || node.Kind != yaml.ScalarNode {
		return ""
	}
	return node.Value
}
